contract InvMutTest {
    C c;
    address deployer;
    constructor(C _c) { c = _c; deployer = msg.sender; }

    // Try various operations from this test contract (which is msg.sender for c calls).
    // We assert that if this contract is not the Owner recorded in c then withdraw() and Command(...) revert,
    // and if this contract is the Owner then withdraw() succeeds and empties the contract balance.
    function run(address payable target, bytes calldata data, uint sendAmt) public payable {
        require(address(this).balance >= sendAmt);

        // observe owner and balance before any action
        address ownerBefore = c.Owner();
        uint balBefore = address(c).balance;

        // Try Command: capture whether it reverts
        bool cmdReverted;
        try c.Command{value: sendAmt}(target, data) {
            cmdReverted = false;
        } catch {
            cmdReverted = true;
        }

        // Observe balance after Command
        uint balAfterCmd = address(c).balance;

        // Try withdraw: capture whether it reverts
        bool wdReverted;
        try c.withdraw{value: 0}() {
            wdReverted = false;
        } catch {
            wdReverted = true;
        }

        // Observe balance after withdraw
        uint balAfterWd = address(c).balance;

        // The general rule asserted:
        // If this contract is the recorded Owner, then withdraw must not revert and after withdraw the contract's balance is 0.
        // If this contract is not the recorded Owner, then withdraw must revert.
        // Additionally, if Command did not revert then it must have been invoked by the Owner (i.e. this contract is Owner).
        assert(
            (address(this) == ownerBefore && wdReverted == false && balAfterWd == 0)
            || (address(this) != ownerBefore && wdReverted == true)
        );

        // Also ensure Command's success implies msg.sender was Owner (i.e., this contract equals ownerBefore)
        assert(cmdReverted || address(this) == ownerBefore);
    }

    receive() external payable {}
}

