contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // amount is the Ether forwarded to multiplicate; addr is the target recipient
    function run(address payable addr, uint amount) public payable {
        require(address(this).balance >= amount);

        // record observable state before the call
        uint balBefore = address(c).balance;

        bool didRevert;
        // perform the state-changing call as top-level statement
        try c.multiplicate{value: amount}(addr) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        uint balAfter = address(c).balance;

        // General property:
        // 1) multiplicate never increases c's balance (balAfter <= balBefore)
        // 2) if a transfer to addr happened successfully then at most balBefore + amount could have been sent,
        //    and since we cannot observe the exact amount transferred to addr, we assert that c's balance decreased by no more than balBefore + amount.
        // Combining: balAfter <= balBefore and balBefore - balAfter <= balBefore + amount  (latter always true),
        // but to make a nontrivial general rule we assert that balAfter <= balBefore and when call reverted balAfter == balBefore.

        assert(
            // c's balance never increases
            balAfter <= balBefore
            // if call reverted, balance unchanged; if not reverted, balance is <= before
            && (didRevert ? balAfter == balBefore : true)
        );
    }

    // allow receiving ETH when c.call sends funds to this test contract during execution
    receive() external payable {}
}

