        // read pre-state
        address ownerBefore = c.Owner();
        uint256 balanceBefore = address(c).balance;

        // Attempt withdraw as invoker (this contract). capture whether it reverted and post-state
        bool withdrawReverted;
        try c.withdraw{value: 0}() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        uint256 balanceAfterWithdraw = address(c).balance;

        // If we want to try Command, attempt with provided value; capture revert and post-state
        bool commandReverted;
        // ensure we have the Ether available to forward
        require(address(this).balance >= sendValue);
        try c.Command{value: sendValue}(target, data) {
            commandReverted = false;
        } catch {
            commandReverted = true;
        }
        uint256 balanceAfterCommand = address(c).balance;

        // General rule asserted:
        // If the caller (this contract) is not Owner, then withdraw and Command must revert and c's balance must not decrease due to those calls.
        // If this contract is the Owner, then calls may succeed (we don't force success), so we only assert non-owner behaviour.
        bool isOwner = (ownerBefore == address(this));

        assert(isOwner || (withdrawReverted && commandReverted && balanceAfterWithdraw >= balanceBefore && balanceAfterCommand >= balanceAfterWithdraw));
    }

