contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function driven by parameters
    // adr: target address passed to multiplicate
    // fund: amount of wei to send when calling multiplicate
    function run(address payable adr, uint256 fund) public payable {
        require(address(this).balance >= fund, "insufficient test balance");

        // observe balance before call
        uint256 before = address(c).balance;

        // perform the call that may transfer out depending on logic
        bool reverted;
        try c.multiplicate{value: fund}(adr) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = address(c).balance;

        // General invariant to assert:
        // - If call reverted, contract balance unchanged.
        // - If call did not revert and fund < before then multiplicate should not have transferred (balance unchanged).
        // - If call did not revert and fund >= before then multiplicate transfers all funds away: after == 0 and adr received at least `before` (we can observe adr via address(this).balance? we cannot observe external balances, but we can at least assert contract lost all funds).
        // We express only observable properties: before, after, fund, and reverted.

        assert(
            // reverted => no change
            (reverted && after == before)
            ||
            // not reverted and fund < before => no change
            (!reverted && fund < before && after == before)
            ||
            // not reverted and fund >= before => contract balance becomes zero
            (!reverted && fund >= before && after == 0)
        );
    }

    receive() external payable {}
}

