        require(address(this).balance >= amount);

        // record balance of c before
        uint balBefore = address(c).balance;

        bool reverted;
        // Call multiplicate with provided amount. This call will be from this contract (which is NOT owner),
        // so normally multiplicate does not require owner. multiplicate has no owner check.
        try c.multiplicate{value: amount}(receiver) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;

        // If the call did not revert and the input amount satisfied the branch condition (amount >= balBefore),
        // then the contract should have forwarded its entire balance (balBefore + amount) to receiver, leaving C with zero balance.
        // We assert this general relationship linking inputs, observed balances, and revert flag.
        assert(
            // either it reverted,
            reverted ||
            // or if it didn't revert then either the branch did not trigger (amount < balBefore) and balance unchanged,
            (amount < balBefore && balAfter == balBefore) ||
            // or the branch triggered (amount >= balBefore) and c's balance becomes zero afterwards
            (amount >= balBefore && balAfter == 0)
        );
    }

    // allow receiving refunds if needed
    receive() external payable {}
}

