contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an amount to send when calling multiplicate and an address to receive.
    // The test will observe address(c).balance before and after, and whether the call reverted.
    function run(address payable adr, uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient funds to forward");

        // Read balance before
        uint256 before = address(c).balance;

        // Call multiplicate forwarding 'amount' wei and record if it reverted
        bool reverted;
        try c.multiplicate{value: amount}(adr) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = address(c).balance;

        // General rule:
        // - If amount < before then multiplicate's body cannot trigger the transfer branch
        //   (which requires msg.value >= address(this).balance), so the call must not have
        //   transferred Ether out of c. Also the function has no other require that can fail
        //   in that case, so it must not revert when amount < before.
        // - If amount >= before then either it may succeed and drain c (after == 0) or revert
        //   (reverted == true). We therefore assert the iff relationships capturing these
        //   behaviors.
        assert(
            // Case A: amount < before  => call did not revert && balance unchanged
            ((amount < before) && (reverted == false) && (after == before))
            ||
            // Case B: amount >= before => either succeeded and c.balance is 0 (transferred out)
            // or it reverted (no guarantee on after when reverted, but reverted==true)
            ((amount >= before) && ((reverted == true) || (after == 0)))
        );
    }

    receive() external payable {}
}

